"A local command (stdio)": "Yerel bir komut (stdio)",
"A menu of up to four shortcuts into that tab, such as Search apps, Update All, the Terminal or a Task Manager page. Slide onto one and let go, or tap it. Navigation above chooses them or turns them off.": "Bu sekmeye en fazla dört kısayoldan oluşan bir menü: Uygulama ara, Tümünü güncelle, Terminal veya bir Görev Yöneticisi sayfası gibi. Parmağınızı birinin üzerine kaydırıp bırakın ya da ona dokunun. Yukarıdaki Gezinme bölümünde seçilir veya kapatılır.",
"A muted theme with a blend of desaturated colors": "Doygunluğu azaltılmış renklerin karışımından oluşan sönük bir tema",
"A name can't contain spaces or control characters": "Ad boşluk veya denetim karakteri içeremez",
"A name can't start with a dash": "Ad tire ile başlayamaz",
"A name cannot contain a slash": "Ad eğik çizgi içeremez",
"A name cannot hold a slash": "Ad eğik çizgi içeremez",
"A name is already taken": "Bu ad zaten kullanılıyor",
"A new code was made": "Yeni kod oluşturuldu",
"A new folder named after the archive": "Arşivin adıyla yeni bir klasör",
"A new key will be made on the next patch": "Bir sonraki yamada yeni bir anahtar oluşturulacak",
"A newer version comes with this app.": "Bu uygulamayla daha yeni bir sürüm geliyor.",
"A notification shows how far they are, with Pause all and Cancel, and the downloads go on when you leave the app or the screen goes off.": "Bir bildirim ilerlemeyi gösterir; Tümünü duraklat ve İptal düğmeleri vardır. Uygulamadan çıksanız veya ekran kapansa da indirmeler sürer.",
"A part can’t start or end with a hyphen.": "Bir bölüm tireyle başlayamaz veya bitemez.",
"A patch bundle asked the patcher for something this build of the app does not have, so it was made for a different Morphe version. Update the source in Sources; if it still happens, report it with the log.": "Bir yama paketi, yamalayıcıdan bu uygulama sürümünde olmayan bir şey istedi; yani farklı bir Morphe sürümü için yapılmış. Kaynaklar’dan kaynağı güncelleyin; yine olursa günlükle birlikte bildirin.",
"A patch could not be applied. This usually means the patch does not fit this version of the app. Check the details below and the log.": "Bir yama uygulanamadı. Bu genellikle yamanın uygulamanın bu sürümüne uymadığı anlamına gelir. Aşağıdaki ayrıntılara ve günlüğe bakın.",
"A patch source decides what ends up inside your patched apps. Only add sources you trust. It is downloaded now and listed under Sources.": "Bir yama kaynağı, yamalı uygulamalarınızın içine neyin gireceğine karar verir. Yalnızca güvendiğiniz kaynakları ekleyin. Şimdi indirilir ve Kaynaklar’da listelenir.",
"A path exclusion keeps one file or folder, and everything inside it, out of the tools you pick.": "Yol dışlaması, bir dosyayı veya klasörü ve içindeki her şeyi seçtiğiniz araçların dışında tutar.",
"A persistent Shizuku shell: cd and exports stick. Type exit or tap Exit Rish to leave.": "Kalıcı bir Shizuku shell’i: cd ve export’lar korunur. Çıkmak için exit yazın veya “Rish’ten çık” düğmesine dokunun.",
"A phone cannot answer after a reboot, so the sheet says what to expect instead; if nothing happens within ten seconds it says so and shows what the command printed. Recovery and Bootloader land on screens with their own buttons: Reboot system now (recovery) or START (bootloader) brings Android back.": "Telefon yeniden başladıktan sonra yanıt veremez, bu yüzden sayfa bunun yerine ne bekleneceğini söyler; on saniye içinde hiçbir şey olmazsa bunu söyler ve komutun yazdırdığını gösterir. Recovery ve Bootloader kendi düğmeleri olan ekranlara götürür: Reboot system now (recovery) veya START (bootloader) Android'i geri getirir.",
"A phone without zram, or one whose shell may not read the counters, shows Not available with the reason. The numbers are a snapshot; they move as apps run.": "zram'ı olmayan ya da kabuğu sayaçları okuyamayan bir telefon, nedeniyle birlikte Kullanılamıyor gösterir. Sayılar bir anlık görüntüdür; uygulamalar çalıştıkça değişir.",
"A remote address, SSE": "Uzak bir adres, SSE",
"A remote address, streamable HTTP": "Uzak bir adres, streamable HTTP",
"A repository: the app will look for its catalog (index-v2.json or index-v1.jar).": "Bir depo: uygulama kataloğunu arar (index-v2.json veya index-v1.jar).",
"A row": "Bir satır",
"A saturated theme that uses a wide range of colors": "Geniş bir renk yelpazesi kullanan doygun bir tema",
"A search is still running": "Bir arama hâlâ sürüyor",
"A segment exclusion matches a name segment, like \"DCIM/Camera\", wherever it is.": "Bölüm dışlaması, “DCIM/Camera” gibi bir ad bölümüyle, nerede olursa olsun eşleşir.",
"A setting that is on or off": "Açık veya kapalı olan bir ayar",
"A setting without a description": "Açıklaması olmayan bir ayar",
"A sheet with every action for that app: settings, launch, force stop, enable or disable, uninstall, suspend, permissions, activities. Choose which ones it lists in the Action Button card above.": "O uygulamanın tüm eylemlerini içeren bir alt sayfa: ayarlar, başlat, durmaya zorla, etkinleştir veya devre dışı bırak, yüklemeyi kaldır, askıya al, izinler, activity’ler. Hangilerinin listeleneceğini yukarıdaki Eylem düğmesi kartında seçin.",
"A short tick you feel when you tap": "Dokunduğunuzda hissedilen kısa bir tık",
"A short vibration for every button, tab, switch and list row you tap. On by default. It is only the app's own tick: the phone's own touch feedback setting is not changed.": "Dokunduğunuz her düğme, sekme, anahtar ve liste satırı için kısa bir titreşim. Varsayılan olarak açık. Bu yalnızca uygulamanın kendi tıkıdır: telefonun dokunma geri bildirimi ayarı değiştirilmez.",
"A small knowledge graph the agent can read and write between turns.": "Ajanın yanıtlar arasında okuyup yazabildiği küçük bir bilgi grafiği.",
"A source is a bundle of patches. Turn a source off to keep it without using it: a source that is off is not loaded. More sources are in the Community tab.": "Kaynak, bir yama paketidir. Kullanmadan saklamak için kaynağı kapatın: kapalı bir kaynak yüklenmez. Daha fazla kaynak Topluluk sekmesinde.",
"A strong accent on a plain grey background.": "Düz gri bir arka planda güçlü bir vurgu.",
"A strong accent that stands out against no background tint": "Arka plan tonu olmadan öne çıkan güçlü bir vurgu",
"A tab needs a name": "Sekmenin bir adı olmalı",
"A tab on the bottom bar": "Alt çubuktaki bir sekme",
"A value can't contain a carriage return (use plain line breaks)": "Değer satır başı (CR) karakteri içeremez (normal satır sonları kullanın)",
"A value can't contain control characters": "Değer denetim karakterleri içeremez",
"A value with several lines.": "Birden çok satırlı bir değer.",
"A web address or URI.": "Bir web adresi veya URI.",
"A whole number.": "Tam sayı.",
"A working mode (ADB, Shizuku or root) is ready. Grant all remaining permissions with it now? The app restarts afterwards.": "Bir çalışma modu (ADB, Shizuku veya Root) hazır. Kalan tüm izinler şimdi onunla verilsin mi? Ardından uygulama yeniden başlar.",
"A wrong value can make the device misbehave. Delete takes the setting away so the system falls back to its default.": "Yanlış bir değer cihazın hatalı çalışmasına neden olabilir. Sil, ayarı kaldırır; böylece sistem varsayılanına döner.",
