"Adaptive brightness adjustment (-1 to 1)": "Uyarlanabilir parlaklık ayarı (-1 ile 1 arası)",
"Adaptive brightness bias": "Parlaklık kayması",
"Adaptive brightness is off, so this has no effect until you turn it on.": "Uyarlanabilir parlaklık kapalı, bu yüzden siz açana kadar bunun bir etkisi olmaz.",
"Adaptive brightness picks the screen brightness from the light sensor. This value (Android calls it screen_auto_brightness_adj, from −1 to 1) shifts every choice darker or brighter: 0 is neutral, +0.5 noticeably brighter, −0.5 noticeably darker. It is the same thing the brightness slider changes while adaptive brightness is on.": "Uyarlanabilir parlaklık, ekran parlaklığını ışık sensöründen seçer. Bu değer (Android buna screen_auto_brightness_adj der, −1 ile 1 arası) her seçimi daha karanlığa veya daha parlağa kaydırır: 0 nötr, +0,5 belirgin biçimde daha parlak, −0,5 belirgin biçimde daha karanlık. Uyarlanabilir parlaklık açıkken parlaklık kaydırıcısının değiştirdiği şeyin aynısıdır.",
