"AppCleaner can clear the caches that no file access can reach (the \"Clear cache\" button of an app's Storage screen) by tapping through the system settings for you. For that it needs this app's accessibility service. The service only acts while AppCleaner is clearing caches: it opens the App info screen of one app after the other, taps Clear cache, and stops when the screen turns off or locks. A cover over the screen shows what it is doing, with a way to cancel. Nothing is read or sent anywhere. On Android 13 and newer, an app installed from a file may first need \"Allow restricted settings\" (App info of this app, the three dots menu).": "AppCleaner, hiçbir dosya erişiminin ulaşamadığı önbellekleri (bir uygulamanın Depolama ekranındaki “Önbelleği temizle” düğmesi) sizin yerinize sistem ayarlarına dokunarak temizleyebilir. Bunun için bu uygulamanın erişilebilirlik hizmetine ihtiyaç duyar. Hizmet yalnızca AppCleaner önbellekleri temizlerken çalışır: sırayla her uygulamanın Uygulama bilgisi ekranını açar, Önbelleği temizle’ye dokunur ve ekran kapandığında veya kilitlendiğinde durur. Ekranın üzerindeki bir örtü ne yaptığını gösterir ve iptal etmenin bir yolunu sunar. Hiçbir şey okunmaz veya herhangi bir yere gönderilmez. Android 13 ve üzerinde, dosyadan yüklenen bir uygulama için önce “Kısıtlanmış ayarlara izin ver” gerekebilir (bu uygulamanın Uygulama bilgisi, üç nokta menüsü).",
