"Aurora Store is an open-source Play Store client. Automatic Play version detection is a planned follow-up (it needs anonymous Play authentication); for now this routes each app to its store page, opening Aurora Store when it's installed.": "Aurora Store, açık kaynaklı bir Play Store istemcisidir. Play sürümünün otomatik algılanması planlanan bir sonraki adımdır (anonim Play kimlik doğrulaması gerekir); şimdilik her uygulamayı mağaza sayfasına yönlendirir ve Aurora Store yüklüyse onu açar.",
"Aurora Store: installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store: yüklü · Play Store: yüklü. Mağaza sayfasını açmak için aşağıdaki bir uygulamaya dokunun.",
"Aurora Store: installed · Play Store: not installed. Tap an app below to open its store page.": "Aurora Store: yüklü · Play Store: yüklü değil. Mağaza sayfasını açmak için aşağıdaki bir uygulamaya dokunun.",
"Aurora Store: not installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store: yüklü değil · Play Store: yüklü. Mağaza sayfasını açmak için aşağıdaki bir uygulamaya dokunun.",
"Aurora Store: not installed · Play Store: not installed. Tap an app below to open its store page.": "Aurora Store: yüklü değil · Play Store: yüklü değil. Mağaza sayfasını açmak için aşağıdaki bir uygulamaya dokunun.",
