"Choose the sign-in method in the agent's Connect sheet. The tools are installed into a Debian environment inside Termux when they have no Android build. This takes several minutes and up to about 1 GB; the providers do not support Android officially, so a tool may not run on every phone.": "Oturum açma yöntemini ajanın Bağlantı sayfasında seçin. Android sürümü olmayan araçlar, Termux içindeki bir Debian ortamına yüklenir. Bu birkaç dakika sürer ve en fazla yaklaşık 1 GB yer kaplar; sağlayıcılar Android’i resmî olarak desteklemediği için bir araç her telefonda çalışmayabilir.",
"Choose the version and tap its download button. The file is saved here and the browser closes by itself.": "Sürümü seçin ve indirme düğmesine dokunun. Dosya buraya kaydedilir ve tarayıcı kendiliğinden kapanır.",
"Choose what the extra button on each row of the Apps list does. It is always an icon, and the ones that change with the app (Enable / Disable, Install / Uninstall, Unsuspend / Suspend) switch their icon and action to match the app's current state.": "Uygulamalar listesinin her satırındaki ek düğmenin ne yaptığını seçin. Her zaman bir simgedir; uygulamaya göre değişenler (Etkinleştir / Devre dışı bırak, Yükle / Yüklemeyi kaldır, Askıdan çıkar / Askıya al) simgesini ve eylemini uygulamanın geçerli durumuna uyacak şekilde değiştirir.",
"Choose what the menu of each pinned tab lists and in what order. A menu lists four at most; the first one is the one under your thumb.": "Sabitlenen her sekmenin menüsünde neyin hangi sırayla listeleneceğini seçin. Bir menü en fazla dört öğe listeler; ilki başparmağınızın altında olur.",
"Choose what to install and which starter files to write": "Neyin yükleneceğini ve hangi başlangıç dosyalarının yazılacağını seçin",
"Choosing a folder needs the app build": "Klasör seçmek için uygulama sürümü gerekir",
"Choosing files works in the app": "Dosya seçme uygulamada çalışır",
