"Claude (Anthropic)": "Claude (Anthropic)",
"Claude Code": "Claude Code",
"Claude Pro or Max and a Google account login may only be used in the providers' own apps: Anthropic and Google do not allow other apps to use those logins. So the Terminal signs you in through the official command-line tools running in Termux, where the provider's own website login opens:": "Claude Pro veya Max hesabıyla ve Google hesabıyla oturum açma, yalnızca sağlayıcıların kendi uygulamalarında kullanılabilir: Anthropic ve Google, başka uygulamaların bu oturum açma yöntemlerini kullanmasına izin vermez. Bu yüzden Terminal, Termux’ta çalışan resmî komut satırı araçları üzerinden oturum açmanızı sağlar; sağlayıcının kendi web sitesindeki oturum açma sayfası orada görüntülenir:",
"Clean up what is not needed any more: superfluous files, the expendable data of apps, the leftovers of apps that are gone, and files that exist twice. Scan first, look at the list, take out what you want to keep, then delete. The four tools use the working mode of this app for the folders a normal app cannot read.": "Artık gerekmeyenleri temizleyin: gereksiz dosyalar, uygulamaların atılabilir verileri, silinmiş uygulamaların kalıntıları ve iki kez bulunan dosyalar. Önce tarayın, listeye bakın, tutmak istediklerinizi çıkarın, sonra silin. Dört araç, normal bir uygulamanın okuyamadığı klasörler için bu uygulamanın çalışma modunu kullanır.",
"Clean — no engine flagged this file": "Temiz — hiçbir motor bu dosyayı işaretlemedi",
"CleanBrowsing Adult": "CleanBrowsing Adult",
"CleanBrowsing Family": "CleanBrowsing Family",
"CleanBrowsing Security": "CleanBrowsing Security",
"Cleanup is simulated. Files are scanned and reported, but nothing is actually deleted.": "Temizlik simüle edilir. Dosyalar taranır ve raporlanır, ancak gerçekte hiçbir şey silinmez.",
