"Each agent keeps this in its own file, the same way its official sign-in does, so two or more agents can carry the same server and either can be used with it. Codex keeps a remote server's token as an environment variable instead of in its file. Not tested against every version of every tool.": "Her ajan bunu, resmî oturum açma bilgisini tuttuğu gibi kendi dosyasında saklar; böylece iki veya daha fazla ajan aynı sunucuyu taşıyabilir ve herhangi biri onunla kullanılabilir. Codex, uzak bir sunucunun belirtecini dosyasında değil, bir ortam değişkeni olarak saklar. Her aracın her sürümüyle test edilmemiştir.",
"Each part between dots can be 63 characters at most.": "Noktalar arasındaki her bölüm en fazla 63 karakter olabilir.",
"Each part between dots needs at least one character.": "Noktalar arasındaki her bölümde en az bir karakter olmalı.",
"Each shell keeps its own screen and stays open while you use other tabs: cd, export and variables carry over from one command to the next. Restart shell starts a fresh one.": "Her shell kendi ekranını korur ve siz diğer sekmeleri kullanırken açık kalır: cd, export ve değişkenler bir komuttan diğerine aktarılır. “Shell’i yeniden başlat” yepyeni bir shell açar.",
"Each wait is 600 seconds (10 minutes) at most.": "Her bekleme en fazla 600 saniyedir (10 dakika).",
"Earlier certificates (the signing key was changed)": "Önceki sertifikalar (imzalama anahtarı değiştirildi)",
