"Frees only the page cache (copies of files the kernel keeps in RAM so they open faster). Apps are not touched. Android fills it again as apps read files.": "Yalnızca sayfa önbelleğini boşaltır (çekirdeğin dosyaların daha hızlı açılması için RAM'de tuttuğu kopyalar). Uygulamalara dokunulmaz. Uygulamalar dosya okudukça Android onu yeniden doldurur.",
