"Lenovo": "Lenovo",
"Leon is an open-source personal assistant (skills, voice) that runs on a computer with Node.js and Python. It has no Android version and is not a coding agent, so it does not chat in this Terminal.": "Leon, Node.js ve Python ile bir bilgisayarda çalışan açık kaynaklı bir kişisel asistandır (beceriler, ses). Android sürümü yoktur ve bir kodlama ajanı olmadığı için bu Terminal’de sohbet etmez.",
"Leon.ai": "Leon.ai",
"Let Termux take commands from other apps": "Termux’un diğer uygulamalardan komut almasına izin ver",
"Let them act without asking": "Sormadan işlem yapmalarına izin ver",
"Lets the agent read and write files under the folder named at the end of the command (change /sdcard to taste).": "Ajanın, komutun sonunda adı geçen klasörün altındaki dosyaları okumasına ve yazmasına izin verir (/sdcard yerine istediğinizi yazın).",
"Lets the agent think in explicit steps before it acts.": "Ajanın harekete geçmeden önce açık adımlar halinde düşünmesini sağlar.",
"Lets this app change a few protected system settings used by some advanced features.": "Bu uygulamanın, bazı gelişmiş özelliklerin kullandığı birkaç korumalı sistem ayarını değiştirmesine izin verir.",
"Lets this app install the package files you choose, such as APK, APKS and XAPK files from your storage.": "Bu uygulamanın, depolama alanınızdan seçtiğiniz APK, APKS ve XAPK gibi paket dosyalarını yüklemesine izin verir.",
"Lets this app open another app's screen from the background, such as an app you have just installed.": "Bu uygulamanın arka plandan başka bir uygulamanın ekranını açmasına, örneğin yeni yüklediğiniz bir uygulamayı açmasına izin verir.",
"Lets this app read the phone's own status reports (dumpsys), such as battery, power and memory details, without asking the shell each time. Granted through the working mode.": "Bu uygulamanın telefonun kendi durum raporlarını (dumpsys), örneğin pil, güç ve bellek ayrıntılarını, her seferinde kabuğa sormadan okumasına izin verir. Çalışma modu üzerinden verilir.",
"Android's permission to read the system log (logcat) of every app. Live Logcat does not use it: it reads the log through the working mode. Granted through the working mode.": "Tüm uygulamaların sistem günlüğünü (logcat) okumak için Android izni. Canlı Logcat bunu kullanmaz: günlüğü çalışma modu üzerinden okur. Çalışma modu üzerinden verilir.",
"Lets this app show its notifications, such as the Wireless debugging pairing prompt and the progress of a long job.": "Bu uygulamanın, Kablosuz hata ayıklama eşleme istemi ve uzun bir işin ilerlemesi gibi bildirimlerini göstermesini sağlar.",
