"Nothing changes until you tap Apply. The card reads the three scales back and shows what the phone really holds.": "Uygula’ya dokunana kadar hiçbir şey değişmez. Kart üç ölçeği geri okur ve telefonun gerçekte ne tuttuğunu gösterir.",
"Nothing changes until you tap Apply. The card reads the value back and shows what the phone really holds.": "Uygula’ya dokunana kadar hiçbir şey değişmez. Kart değeri geri okur ve telefonun gerçekte ne tuttuğunu gösterir.",
"Nothing changes until you tap a service. The card reads the phone back and shows what it really holds.": "Bir hizmete dokunana kadar hiçbir şey değişmez. Kart telefonu yeniden okur ve gerçekte ne olduğunu gösterir.",
