"Nothing found. Both devices must be on the same Wi-Fi network, with wireless debugging on. You can also type the address by hand under Wi-Fi.": "Hiçbir şey bulunamadı. Her iki cihaz da aynı Wi-Fi ağında olmalı ve kablosuz hata ayıklama açık olmalıdır. Adresi Wi-Fi altında elle de yazabilirsiniz.",
"Nothing found. Keep the Wireless Debugging screen open and enter the ports manually.": "Hiçbir şey bulunamadı. Kablosuz hata ayıklama ekranını açık tutun ve portları elle girin.",
"Nothing happened within 10 seconds, although the command reported no error: the mode could not do it.": "Komut hata bildirmediği halde 10 saniye içinde hiçbir şey olmadı: mod bunu yapamadı.",
"Nothing happened within 10 seconds: the mode could not do it.": "10 saniye içinde hiçbir şey olmadı: mod bunu yapamadı.",
