"Temporary root is granted inside your root manager, such as KernelSU or APatch. Open it, allow this app Super User there, then come back and let the app switch to Root. If this app is not in its list (some root managers list an app only after it has asked for su), tap Request Super User first. Root Features unlock once su is granted.": "Geçici root, KernelSU veya APatch gibi root yöneticinizin içinde verilir. Açın, orada bu uygulamaya Super User izni verin, sonra geri dönün ve uygulamanın Root’a geçmesine izin verin. Bu uygulama listesinde yoksa (bazı root yöneticileri bir uygulamayı yalnızca su istedikten sonra listeler), önce “Superuser iste” düğmesine dokunun. su verildiğinde Root özellikleri açılır.",
