"The dot in each row moves at the speed you chose, so you see the effect before you apply it. A number above 10 is allowed but makes the phone feel very slow; Reset to 1× brings everything back to normal.": "Her satırdaki nokta seçtiğiniz hızda hareket eder, böylece etkiyi uygulamadan önce görürsünüz. 10’un üzerinde bir sayıya izin verilir ama telefon çok yavaş hissettirir; 1× olarak sıfırla her şeyi normale döndürür.",
