"What the phone is doing right now: memory, storage and battery, with the model and software underneath. Reads only, nothing changes.": "Telefonun şu an ne yaptığı: bellek, depolama ve pil, altında model ve yazılım. Yalnızca okur, hiçbir şey değişmez.",
