"What this tab does when a device you were connected to drops (Wi-Fi, Wireless debugging and Bluetooth devices; a cable is never retried on its own)": "Bağlı olduğunuz bir cihaz koptuğunda bu sekmenin yaptığı (Wi-Fi, Kablosuz hata ayıklama ve Bluetooth cihazları; kablo asla kendiliğinden yeniden denenmez)",
