"When deleting duplicates, SD Maid decides which file to keep by checking each criterion in order. The first criterion that produces a clear winner determines the result. Drag to reorder, tap to change mode.": "Yinelenenleri silerken SD Maid, her ölçütü sırayla denetleyerek hangi dosyayı tutacağına karar verir. Net bir kazanan çıkaran ilk ölçüt sonucu belirler. Yeniden sıralamak için sürükleyin, modu değiştirmek için dokunun.",
"When the chosen source does not have the version or does not work, This version, Newest and All versions go on with the next source, in the order above, until one delivers.": "Seçilen kaynakta sürüm yoksa ya da çalışmıyorsa, Bu sürüm, En yeni ve Tüm sürümler yukarıdaki sırayla bir sonraki kaynakla devam eder, biri sonuç verene kadar.",
"Where the tabs are. The bottom bar holds the tabs you pin and a More button for the rest; the top bar holds all of them.": "Sekmelerin yeri. Alt çubukta sabitlediğiniz sekmeler ve diğerleri için bir “Daha fazla” düğmesi bulunur; üst çubukta hepsi bulunur.",
"Where the whole palette comes from": "Paletin tamamının nereden geldiği",
