"Whoever gets this file can sign apps as you, and Android will install them as updates of the apps you patched here. Send it only to a place that only you can open.": "Bu dosyayı alan kişi uygulamaları sizin adınıza imzalayabilir ve Android bunları burada yamaladığınız uygulamaların güncellemesi olarak kurar. Yalnızca sizin açabileceğiniz bir yere gönderin.",
