"Getting the details from Google Fonts…": "Ayrıntılar Google Fonts’tan alınıyor…",
"Getting the list of fonts from Google Fonts…": "Yazı tipi listesi Google Fonts’tan alınıyor…",
"Google Fonts": "Google Fonts",
"Google Fonts lists no font files for this family.": "Google Fonts bu yazı tipi ailesi için hiçbir dosya listelemiyor.",
